import triton

import triton.language as tl

@triton.jit
def _gemv(X, W, Y, N: tl.constexpr, K: tl.constexpr,
          ROWS: tl.constexpr, BK: tl.constexpr):
    n = tl.program_id(0) * ROWS + tl.arange(0, ROWS)
    k = tl.arange(0, BK)
    x = tl.load(X + k, k < K, other=0).to(tl.float32)
    w = tl.load(W + n[:, None] * K + k[None, :],
                (n[:, None] < N) & (k[None, :] < K), other=0).to(tl.float32)
    tl.store(Y + n, tl.sum(w * x[None, :], 1), n < N)

@triton.jit
def _small_gemm(X, W, P, Y, M: tl.constexpr, N: tl.constexpr,
                K: tl.constexpr, S: tl.constexpr, BM: tl.constexpr,
                BN: tl.constexpr, BK: tl.constexpr):
    mt: tl.constexpr = tl.cdiv(M, BM)
    tile = tl.program_id(0)
    m = (tile % mt) * BM + tl.arange(0, BM)
    n = (tile // mt) * BN + tl.arange(0, BN)
    split = tl.program_id(1)
    k = split * (K // S) + tl.arange(0, BK)
    acc = tl.full((BN, BM), 0, tl.float32)
    for _ in range(K // (S * BK)):
        w = tl.load(W + n[:, None] * K + k[None, :], n[:, None] < N, other=0)
        x = tl.load(X + m[None, :] * K + k[:, None], m[None, :] < M, other=0)
        acc = tl.dot(w, x, acc)
        k += BK
    offsets = m[None, :] * N + n[:, None]
    mask = (m[None, :] < M) & (n[:, None] < N)
    if S == 1:
        tl.store(Y + offsets, acc, mask)
    else:
        tl.extra.cuda.gdc_launch_dependents()
        tl.store(P + split * M * N + offsets, acc, mask)

@triton.jit
def _reduce_projection(P, Y, TOTAL: tl.constexpr, S: tl.constexpr,
                       BLOCK: tl.constexpr):
    tl.extra.cuda.gdc_wait()
    i = tl.program_id(0) * BLOCK + tl.arange(0, BLOCK)
    s = tl.arange(0, S)
    x = tl.load(P + s[:, None] * TOTAL + i[None, :], i[None, :] < TOTAL, other=0)
    tl.store(Y + i, tl.sum(x, 0), i < TOTAL)

def _project(x, state, name):
    w = state["dense"][name]
    m, k = x.shape
    n = 1024 if name == "unpooler" and m <= 8 else w.shape[0]
    if m == 1:
        y = torch.empty((m, n), dtype=x.dtype, device=x.device)
        _gemv[(triton.cdiv(n, 4 if k <= 1024 else 1),)](
            x, w, y, n, k, ROWS=4 if k <= 1024 else 1,
            BK=triton.next_power_of_2(k), num_warps=4)
        return y
    small = (name in ("qkv_gate", "pooler") and m <= 32)
    orient = (name == "o" and m <= 32)
    sliced = name == "unpooler" and m <= 8
    if small or orient or sliced:
        bm, bn, bk = (16 if m <= 16 else 32), 64, (64 if sliced else 128)
        splits = 1 if orient else 16 if sliced else 8 if name == "qkv_gate" else 4
        y = torch.empty((m, n), dtype=x.dtype, device=x.device)
        partial = torch.empty((splits, m, n), dtype=torch.float32, device=x.device) if splits > 1 else y
        _small_gemm[(triton.cdiv(m, bm) * triton.cdiv(n, bn), splits)](
            x, w, partial, y, m, n, k, splits, bm, bn, bk,
            num_warps=4, num_stages=3 if splits > 1 else 4)
        if splits > 1:
            _reduce_projection[(triton.cdiv(m * n, 256),)](
                partial, y, m * n, splits, 256, num_warps=4, launch_pdl=True)
        return y
    if name in state["dense_t"]:
        return torch.mm(x, state["dense_t"][name][:, :n])
    return torch.mm(x, w[:n].T)


# Source: decode/boundaries.py
@triton.jit
def _norm(X, W, Y, N: tl.constexpr, EPS: tl.constexpr, BLOCK: tl.constexpr):
    t = tl.program_id(0)
    d = tl.arange(0, BLOCK)
    x = tl.load(X + t * N + d, d < N, other=0).to(tl.float32)
    w = tl.load(W + d, d < N, other=0).to(tl.float32)
    y = x * tl.rsqrt(tl.sum(x * x, 0) / N + EPS) * (1. + w)
    tl.store(Y + t * N + d, y, d < N)

@triton.jit
def _boundary(STREAM, BRANCH, ALPHA, BETA, POST_W, PRE_W,
               HIDDEN_OUT, STREAM_OUT, ROUTER_OUT,
               WIDTH: tl.constexpr, SCALED: tl.constexpr,
               WRITE_ROUTER: tl.constexpr):
    t = tl.program_id(0)
    d = tl.arange(0, 8192)
    branch = tl.load(BRANCH + t * WIDTH + d, d < WIDTH, other=0).to(tl.float32)
    if SCALED:
        post = tl.load(POST_W + d).to(tl.float32)
        branch = (branch * (1. + post)).to(tl.bfloat16).to(tl.float32)
    branch *= tl.rsqrt(tl.sum(branch * branch, 0) / 8192 + 1e-8)
    old = tl.load(STREAM + t * 8192 + d)
    alpha = tl.load(ALPHA + d)
    beta = tl.load(BETA + d)
    stream = alpha * old + beta * branch
    tl.store(STREAM_OUT + t * 8192 + d, stream)
    pre = tl.load(PRE_W + d).to(tl.float32)
    hidden = stream * tl.rsqrt(tl.sum(stream * stream, 0) / 8192 + 1e-5) * (1. + pre)
    tl.store(HIDDEN_OUT + t * 8192 + d, hidden)
    if WRITE_ROUTER:
        tl.store(ROUTER_OUT + t * 8192 + d, hidden)

def _residual_boundary(stream, branch, state, final=False):
    w = state["weights"]
    prefix = "ffn" if final else "attn"
    hidden = torch.empty(stream.shape, dtype=torch.bfloat16, device=stream.device)
    updated = torch.empty_like(stream)
    write_router = not final and stream.shape[0] <= 8
    router = torch.empty_like(stream) if write_router else hidden
    _boundary[(stream.shape[0],)](
        stream, branch, state[prefix + "_alpha"], state[prefix + "_beta"],
        w["post_ffn_norm"], w["next_pre_attn_norm" if final else "pre_ffn_norm"],
        hidden, updated, router, branch.shape[1], final, write_router,
        num_warps=8, enable_fp_fusion=False)
    return hidden, updated, router


